#!/usr/bin/env bash
# step58 — Categories CRUD: inline edit (name/tag) + delete, added to the admin.
# (add/hide already existed.) products.category_id is ON DELETE SET NULL.
set -euo pipefail
APP=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BAK=$APP/.bak-step58-$TS
mkdir -p "$BAK/routes" "$BAK/views/admin"
cp "$APP/routes/adminCatalog.js" "$BAK/routes/adminCatalog.js"
cp "$APP/views/admin/categories.ejs" "$BAK/views/admin/categories.ejs"
restore(){ echo "!! rollback"; cp "$BAK/routes/adminCatalog.js" "$APP/routes/adminCatalog.js"; cp "$BAK/views/admin/categories.ejs" "$APP/views/admin/categories.ejs"; pm2 restart gsz --update-env >/dev/null 2>&1 || true; }
trap 'restore' ERR
writef(){ local dest="$APP/$1" b64="$2" md5="$3"; base64 -d "$b64" > "$dest"; local got; got=$(md5sum "$dest"|awk '{print $1}'); echo "   $1 $got $([ "$got" = "$md5" ] && echo OK || echo MISMATCH)"; [ "$got" = "$md5" ] || { echo "!! md5 mismatch $1"; false; }; }
cat > /tmp/s58_acat.b64 <<'B58_acat'

B58_acat
writef "routes/adminCatalog.js" /tmp/s58_acat.b64 "8bec79e61eef770dae3ecf3217bd8007"
rm -f /tmp/s58_acat.b64
cat > /tmp/s58_cats.b64 <<'B58_cats'

B58_cats
writef "views/admin/categories.ejs" /tmp/s58_cats.b64 "8c5e7db26ca55bdc0187d8e09e03b5ae"
rm -f /tmp/s58_cats.b64
echo "==> node --check + ejs compile"
node --check "$APP/routes/adminCatalog.js"
node -e 'const ejs=require("/opt/gsz/node_modules/ejs"),fs=require("fs");ejs.compile(fs.readFileSync("/opt/gsz/views/admin/categories.ejs","utf8"),{filename:"/opt/gsz/views/admin/categories.ejs"});console.log("   compiled categories.ejs");'
grep -q "categories/:id/delete" "$APP/routes/adminCatalog.js" || { echo "!! delete route missing"; false; }
echo "==> pm2 restart"; pm2 restart gsz --update-env >/dev/null; sleep 3
grep -q '</html>' <<<"$(curl -s -m 15 http://127.0.0.1:3900/ || true)" || { echo "!! home broken"; false; }
CODE=$(curl -s -o /dev/null -w '%{http_code}' -m 10 http://127.0.0.1:3900/admin/categories || true)
echo "   /admin/categories -> HTTP $CODE (302 to login expected)"
[ "$CODE" = "302" ] || [ "$CODE" = "200" ] || { echo "!! admin categories route error ($CODE)"; false; }
trap - ERR
echo "==> step58 OK — categories edit + delete live. Backup: $BAK"
